import argparse
import json
import os
import sys
import time
from urllib.parse import urlparse
from urllib.request import urlopen
from urllib.error import URLError

def process_url(url, cache_file, log_file):
    try:
        with open(cache_file, 'r') as f:
            try:
                cache = json.load(f)
            except (json.JSONDecodeError, FileNotFoundError):
                cache = {}
    except Exception:
        cache = {}

    current_time = time.time()
    parsed_url = urlparse(url)
    url_key = parsed_url.netloc + parsed_url.path

    if url_key in cache and (current_time - cache[url_key]['retrieved_at']) <= 300:
        print(cache[url_key]['body'])
        return "cache_hit", current_time
    else:
        try:
            with urlopen(url, timeout=10) as response:
                body = response.read().decode('utf-8')
                if not body.strip():
                    return "failed", current_time
                print(body)
                cache[url_key] = {
                    'retrieved_at': current_time,
                    'body': body
                }
                return "fetched", current_time
        except URLError:
            return "failed", current_time

def write_cache(cache_file, cache):
    with open(cache_file, 'w') as f:
        json.dump(cache, f, indent=2)

def write_log(log_file, url, event, seconds):
    with open(log_file, 'a') as f:
        log_entry = {
            'url': url,
            'event': event,
            'seconds': seconds
        }
        f.write(json.dumps(log_entry) + '\n')

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('urls_file')
    parser.add_argument('cache_file')
    args = parser.parse_args()

    log_file = os.path.join(os.path.dirname(args.cache_file), 'cacher.log')
    start_time = time.time()

    with open(args.urls_file, 'r') as f:
        urls = [line.strip() for line in f if line.strip()]

    for url in urls:
        last_throttle = time.time()
        while time.time() - last_throttle < 0.5:
            time.sleep(0.1)
        last_throttle = time.time()

        event, seconds = process_url(url, args.cache_file, log_file)
        write_log(log_file, url, event, time.time() - start_time)
        write_cache(args.cache_file, {} if not hasattr(process_url, 'cache') else process_url.cache)

    sys.exit(0 if event == "fetched" for event in [process_url(url, args.cache_file, log_file) for url in urls] else 1)

import argparse
import json
import os
import sys
import time
from urllib.parse import urlparse
from urllib.request import urlopen
from urllib.error import URLError

def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument('urls_file', type=str)
    parser.add_argument('cache_file', type=str)
    return parser.parse_args()

def load_cache(cache_file):
    if not os.path.exists(cache_file):
        return {}
    try:
        with open(cache_file, 'r') as f:
            return json.load(f)
    except json.JSONDecodeError:
        return {}

def save_cache(cache_file, cache_data):
    with open(cache_file, 'w') as f:
        json.dump(cache_data, f)

def get_current_epoch():
    return time.time()

def process_url(url, cache, current_epoch):
    cache_entry = cache.get(url)
    if cache_entry and (current_epoch - cache_entry['retrieved_at'] <= 300):
        return cache_entry['body'], "cache_hit"
    try:
        start_time = time.time()
        with urlopen(url) as response:
            body = response.read().decode('utf-8')
            if not body.strip():
                return None, "failed"
            end_time = time.time()
            event = "fetched"
            return body, event, end_time - start_time
    except URLError:
        return None, "failed"

def log_event(url, event, seconds):
    log_entry = {'url': url, 'event': event, 'seconds': seconds}
    with open('cacher.log', 'a') as f:
        f.write(json.dumps(log_entry) + '\n')

def main():
    args = parse_args()
    urls_file = args.urls_file
    cache_file = args.cache_file

    cache = load_cache(cache_file)
    last_retry_time = 0

    with open(urls_file, 'r', encoding='utf-8') as f:
        for line in f:
            url = line.strip()
            if not url:
                continue

            current_epoch = get_current_epoch()
            body, event, elapsed = process_url(url, cache, current_epoch)

            if body is not None:
                if event == "fetched":
                    cache[url] = {
                        'retrieved_at': current_epoch,
                        'body': body
                    }
                    log_event(url, event, elapsed)
                else:
                    log_event(url, event, 0)
            else:
                log_event(url, "failed", 0)

            if event == "fetched":
                save_cache(cache_file, cache)
                time.sleep(0.5)

            if last_retry_time + 0.5 < time.time():
                last_retry_time = time.time()

    sys.exit(0 if all(cache.get(url)['retrieved_at'] >= get_current_epoch() - 300 for url in cache) else 1)

import json
import os
import sys
import time
from urllib.request import urlopen
from urllib.error import URLError
from datetime import datetime

def main():
    urls_file = sys.argv[1]
    cache_file = sys.argv[2]
    log_file = os.path.splitext(cache_file)[0] + '.log'

    with open(urls_file, 'r', encoding='utf-8') as f:
        urls = [line.strip() for line in f if line.strip()]

    cache = {}
    if os.path.exists(cache_file):
        try:
            with open(cache_file, 'r') as f:
                cache = json.load(f)
        except (json.JSONDecodeError, IOError):
            cache = {}

    start_time = time.time()
    last_fetch_time = 0.0

    for url in urls:
        current_time = time.time()
        elapsed = current_time - start_time

        if url in cache and cache[url]['retrieved_at'] >= current_time - 300:
            print(cache[url]['body'], end='')
            log_entry = {
                'url': url,
                'event': 'cache_hit',
                'seconds': elapsed
            }
        else:
            if current_time - last_fetch_time < 0.5:
                time.sleep(0.5 - (current_time - last_fetch_time))
                last_fetch_time = time.time()
            try:
                with urlopen(url, timeout=10) as response:
                    text = response.read().decode('utf-8')
                    if text:
                        print(text, end='')
                        cache[url] = {
                            'retrieved_at': current_time,
                            'body': text
                        }
                        log_entry = {
                            'url': url,
                            'event': 'fetched',
                            'seconds': elapsed
                        }
                    else:
                        log_entry = {
                            'url': url,
                            'event': 'failed',
                            'seconds': elapsed
                        }
            except URLError:
                log_entry = {
                    'url': url,
                    'event': 'failed',
                    'seconds': elapsed
                }

        with open(log_file, 'a') as f:
            json.dump(log_entry, f)
            f.write('\n')

        with open(cache_file, 'w') as f:
            json.dump(cache, f, indent=2)

        if 'failed' in log_entry:
            sys.exit(1)

if __name__ == '__main__':
    main()
